export function buildAnthropicCcModelsWithSynthetics(stockModels: readonly StockModel[]): ProviderChatModelConfig[] {
	const augmented = [...stockModels];
	for (const synthetic of SYNTHETIC_MODELS) {
		if (!stockModels.some((m) => m.id === synthetic.id)) {
			augmented.push(synthetic);
		}
	}
	return buildAnthropicCcModelsFromStock(augmented);
}

type AnthropicCcOAuthModule = typeof import("./oauth");

function loadAnthropicCcOAuth(): Promise<AnthropicCcOAuthModule> {
	return import("./oauth");
}

export function buildAnthropicCcOAuthConfig() {
	return {
		name: "Anthropic CC (Claude Pro/Max)",
		login: (callbacks: OAuthLoginCallbacks) =>
			loadAnthropicCcOAuth().then((oauth) => oauth.loginAnthropicCc(callbacks)),
		refreshToken: (credentials: OAuthCredentials, signal?: AbortSignal) =>
			loadAnthropicCcOAuth().then((oauth) => oauth.refreshAnthropicCcToken(credentials, signal)),
		getApiKey: (credentials: OAuthCredentials) => credentials.access,
	};
}

export async function buildAnthropicCcModels(): Promise<ProviderChatModelConfig[]> {
	return buildAnthropicCcModelsWithSynthetics(
		getBuiltinModels("anthropic") as readonly StockModel[],
	);
}

export async function getAnthropicCcProviderConfig(): Promise<ProviderConfig> {
	return {
		baseUrl: process.env.ANTHROPIC_CC_BASE_URL ?? "https://api.anthropic.com",
		apiKey: "$ANTHROPIC_CC_API_KEY",
		api: ANTHROPIC_CC_API,
		models: await buildAnthropicCcModels(),
		oauth: buildAnthropicCcOAuthConfig(),
		streamSimple: streamAnthropicCc,
	};
}

