import { sanitizeSurrogates } from "./vendor/sanitize-unicode";
import { getNeutralDocAliasPaths } from "../docAliases";

const IDENTITY_SENTENCE_PREFIX_PATTERNS = [
	/^\s*(?:you are|you're)\s+(?:the\s+)?pi\b[^.?!]*[.?!]\s*/i,
	/^\s*(?:you are|you're)\s+(?:an\s+)?(?:ai\s+)?(?:assistant|agent|coding assistant)(?:\s+named)?\s+pi\b[^.?!]*[.?!]\s*/i,
	/^\s*i am pi\b[^.?!]*[.?!]\s*/i,
	/^\s*(?:you are|you're)\b[^.?!]*\b(?:operating|running)\s+(?:inside|within)\s+pi\b[^.?!]*[.?!]\s*/i,
] as const;

const IDENTITY_LINE_PATTERNS = [
	/^\s*(?:you are|you're)\s+(?:the\s+)?pi\b.*$/i,
	/^\s*(?:you are|you're)\s+(?:an\s+)?(?:ai\s+)?(?:assistant|agent|coding assistant)(?:\s+named)?\s+pi\b.*$/i,
	/^\s*(?:assistant|agent|model)\s+(?:name|identity)\s*:\s*pi\b.*$/i,
	/^\s*i am pi\b.*$/i,
	/^\s*(?:you are|you're)\b.*\b(?:operating|running)\s+(?:inside|within)\s+pi\b.*$/i,
] as const;


const NEUTRAL_DOC_ALIASES = getNeutralDocAliasPaths();

function collapseBlankLines(lines: string[]) {
	return lines.reduce<string[]>((result, line) => {
		const normalized = line.trim().length === 0 ? "" : line;
		if (normalized === "" && result[result.length - 1] === "") return result;
		result.push(normalized);
		return result;
	}, []);
}

function stripIdentitySentencePrefix(line: string) {
	for (const pattern of IDENTITY_SENTENCE_PREFIX_PATTERNS) {
		const replaced = line.replace(pattern, "");
		if (replaced !== line) return replaced.trimStart();
	}
	return line;
}

function rewriteReferenceDocumentationLine(line: string) {
	const leadingWhitespace = line.match(/^\s*/)?.[0] ?? "";
	const trimmed = line.trim();
	if (
		/^Pi documentation \(read only when the user asks about pi itself, its SDK, extensions, themes, skills, or TUI\):\s*$/i.test(trimmed)
	) {
		return `${leadingWhitespace}Reference documentation (read only when the user asks about the local coding agent, its SDK, extensions, themes, skills, or TUI):`;
	}
	if (/^-\s*Main documentation:/i.test(trimmed)) {
		return `${leadingWhitespace}- Main documentation: ${NEUTRAL_DOC_ALIASES.readme}`;
	}
	if (/^-\s*Additional docs:/i.test(trimmed)) {
		return `${leadingWhitespace}- Additional docs: ${NEUTRAL_DOC_ALIASES.docs}`;
	}
	if (/^-\s*Examples:/i.test(trimmed)) {
		return `${leadingWhitespace}- Examples: ${NEUTRAL_DOC_ALIASES.examples} (extensions, custom tools, SDK)`;
	}
	if (/^-\s*When asked about:/i.test(trimmed)) {
		return `${leadingWhitespace}- When asked about: extensions (docs/extensions.md, examples/extensions/), themes (docs/themes.md), skills (docs/skills.md), prompt templates (docs/prompt-templates.md), TUI components (docs/tui.md), keybindings (docs/keybindings.md), SDK integrations (docs/sdk.md), custom providers (docs/custom-provider.md), adding models (docs/models.md), packages (docs/packages.md)`;
	}
	if (/^-\s*When working on pi topics,/i.test(trimmed)) {
		return `${leadingWhitespace}- When working on agent topics, read the docs and examples, and follow .md cross-references before implementing`;
	}
	if (/^-\s*Always read pi \.md files completely/i.test(trimmed)) {
		return `${leadingWhitespace}- Always read the .md files completely and follow links to related docs (e.g., tui.md for TUI API details)`;
	}
	return line;
}

export function sanitizeAnthropicCcSystemPrompt(prompt?: string): string | undefined {
	if (!prompt?.trim()) return undefined;
	const filtered: string[] = [];
	for (const line of sanitizeSurrogates(prompt).split(/\r?\n/)) {
		const strippedLine = rewriteReferenceDocumentationLine(stripIdentitySentencePrefix(line));
		const trimmed = strippedLine.trim();
		if (!trimmed) {
			if (!line.trim()) filtered.push(line);
			continue;
		}
		if (IDENTITY_LINE_PATTERNS.some((pattern) => pattern.test(trimmed))) {
			continue;
		}
		filtered.push(strippedLine);
	}

	const cleaned = collapseBlankLines(filtered).join("\n").trim();
	return cleaned || undefined;
}

import { FALLBACK_VERSION, getClaudeCodeVersion } from "../version";
import { createHash } from "node:crypto";
export interface AnthropicCcBaseline {
	version?: string;
	model: string;
	endpointPath: string;
	userAgent: string;
	betaFlags: string[];
	systemPrelude: string[];
	contextManagement?: Record<string, unknown>;
	outputConfig?: Record<string, unknown>;
	thinking?: Record<string, unknown>;
}


export function resolveAnthropicCcDefaultOutputConfig(modelId: string): Record<string, unknown> | undefined {
	if (
		modelId.includes("claude-opus-4-8") ||
		modelId.includes("claude-opus-4.8") ||
		modelId.includes("claude-opus-4-7") ||
		modelId.includes("claude-opus-4.7") ||
		modelId.includes("claude-fable-5")
	) {
		return { effort: "xhigh" };
	}
	return undefined;
}

export function buildAnthropicCcUserAgent(version: string = FALLBACK_VERSION) {
	return `claude-cli/${version} (external, sdk-cli)`;
}


export function buildAnthropicCcBillingSuffix(
	prompt: string,
	version: string = FALLBACK_VERSION,
): string {
	const picked = [4, 7, 20].map((index) => prompt[index] ?? "0").join("");
	return createHash("sha256").update(`59cf53e54c78${picked}${version}`).digest("hex").slice(0, 3);
}

export function buildCapturedAnthropicCcBillingHeader(
	version: string = FALLBACK_VERSION,
	prompt = "",
	entrypoint = "sdk-cli",
): string {
	return `x-anthropic-billing-header: cc_version=${version}.${buildAnthropicCcBillingSuffix(prompt, version)}; cc_entrypoint=${entrypoint};`;
}

export function resolveAnthropicCcBaselineVersion(baseline: AnthropicCcBaseline): string {
	return baseline.version ?? baseline.userAgent.match(/^claude-cli\/([^ ]+)/)?.[1] ?? FALLBACK_VERSION;
}

export function createAnthropicCcBaseline(version: string = FALLBACK_VERSION): AnthropicCcBaseline {
	return {
		version,
		model: "claude-opus-4-8",
		endpointPath: "/v1/messages?beta=true",
		userAgent: buildAnthropicCcUserAgent(version),
		betaFlags: [
			"claude-code-20250219",
			"interleaved-thinking-2025-05-14",
			"thinking-token-count-2026-05-13",
			"context-management-2025-06-27",
			"prompt-caching-scope-2026-01-05",
			"mid-conversation-system-2026-04-07",
			"per-turn-control-2026-07-01",
			"effort-2025-11-24",
			"fallback-credit-2026-06-01",
		],
		systemPrelude: [
			buildCapturedAnthropicCcBillingHeader(version, ""),
			"You are a Claude agent, built on Anthropic's Claude Agent SDK.",
		],
		contextManagement: {
			edits: [{ type: "clear_thinking_20251015", keep: "all" }],
		},
		thinking: {
			type: "adaptive",
		},
	};
}

let anthropicCcBaseline = createAnthropicCcBaseline(getClaudeCodeVersion().version);

export function getAnthropicCcBaseline() {
	return anthropicCcBaseline;
}

export function setAnthropicCcBaselineVersion(version: string) {
	anthropicCcBaseline = createAnthropicCcBaseline(version);
	return anthropicCcBaseline;
}

export function buildParams(
	model: Model<"anthropic-messages">,
	context: TranscriptContext,
	isOAuthToken: boolean,
	options?: AnthropicOptions,
	strictToolPolicy: { disablePreferredStrictTools?: boolean; hasPreferredStrictTools?: boolean } = {},
): MessageCreateParamsStreaming {
	context = resolveAnthropicTranscript(model, context);
	const { cacheControl } = getCacheControl(model, options?.cacheRetention, options?.env);
	const initialSystemMessage = getInitialSystemMessage(context.messages);
	const initialTools = initialSystemMessage?.toolsAdded ?? [];
	// Inline `tool_definition` blocks express same-name redefinitions, so redefinitions no
	// longer force the collapsed transcript. Beta resolution reuses this same decision.
	const nativeToolChanges = usesAnthropicCcNativeToolChanges(model, context);
	const initialSystemText = initialSystemMessage
		? getSystemMessageText(initialSystemMessage)
		: "";
	const conversationMessages = initialSystemMessage
		? context.messages.slice(1)
		: context.messages;
	const supportsMidConvoEffort = model.compat?.supportsMidConvoEffort === true;
	const usesActiveManagedEffort = recordsManagedEffortFor(model, options);
	const thinkingDisabled = isThinkingDisabled(model, options);
	const activeEffort = options?.effort ?? "high";
	const supportsStrictTools = model.compat?.supportsStrictTools === true;
	const convertRequestToolDefinitions = (tools: Tool[]) => {
		const definitions = convertToolsWithStrictMode(
			tools, isOAuthToken, supportsStrictTools, strictToolPolicy.disablePreferredStrictTools,
		);
		if (definitions.some((definition, index) => {
			const config = tools[index].constrainedSampling;
			return definition.strict === true && !!config && config.type === "json_schema" && config.strict === "prefer";
		})) strictToolPolicy.hasPreferredStrictTools = true;
		return definitions;
	};
	// Native tool changes define every later tool by value in a `tool_addition` block,
	// using the same strict-mode conversion and CC naming as top-level declarations.
	const convertToolDefinitions = nativeToolChanges ? convertRequestToolDefinitions : undefined;
	const messages = convertMessages(
		conversationMessages,
		model,
		isOAuthToken,
		cacheControl,
		supportsMidConvoEffort && !thinkingDisabled ? { provider: model.provider, api: model.api } : undefined,
		convertToolDefinitions,
	);
	if (usesActiveManagedEffort) {
		messages.push({ role: "system", content: [], output_config: { effort: activeEffort } } as MessageParam);
	}
	const params: MessageCreateParamsStreaming = {
		model: model.id,
		messages,
		max_tokens: options?.maxTokens || (model.maxTokens / 3) | 0,
		stream: true,
	};

	// For OAuth tokens, we MUST include Claude Code identity
	if (isOAuthToken) {
		params.system = [
			{
				type: "text",
				text: "You are Claude Code, Anthropic's official CLI for Claude.",
				...(cacheControl ? { cache_control: cacheControl } : {}),
			},
		];
		if (initialSystemText) {
			params.system.push({
				type: "text",
				text: sanitizeSurrogates(initialSystemText),
				...(cacheControl ? { cache_control: cacheControl } : {}),
			});
		}
	} else if (initialSystemText) {
		// Add cache control to system prompt for non-OAuth tokens
		params.system = [
			{
				type: "text",
				text: sanitizeSurrogates(initialSystemText),
				...(cacheControl ? { cache_control: cacheControl } : {}),
			},
		];
	}

	// Pi 0.83: temperature is incompatible with thinking and may also be
	// disabled by stock model compatibility metadata (notably Opus 5).
	if (
		options?.temperature !== undefined &&
		!supportsMidConvoEffort &&
		!options?.thinkingEnabled &&
		model.compat?.supportsTemperature !== false
	) {
		params.temperature = options.temperature;
	}

	if (nativeToolChanges) {
		// The request-level tool list never changes in native mode: later tools are defined
		// by value in `tool_addition` blocks and withdrawn by `tool_removal`, so the cached
		// prefix survives every tool change. anthropic-cc sends no deferred placeholder.
		params.tools = convertRequestToolDefinitions(initialTools);
	} else {
		const currentTools = getCurrentTools(context.messages);
		if (currentTools.length > 0) {
			params.tools = convertRequestToolDefinitions(currentTools);
		}
	}

	// Managed-effort models use bound adaptive thinking; other reasoning models
	// retain their adaptive, budget-based, or explicitly disabled behavior.
	if (thinkingDisabled) {
		(params as any).thinking = { type: "disabled" };
	} else if (usesActiveManagedEffort) {
		(params as any).thinking = {
			type: "adaptive",
			display: options?.thinkingDisplay ?? "summarized",
			block_binding: { prefix_mismatch_behavior: "drop_block" },
		};
		(params as any).output_config = { effort: "high" };
	} else if (model.reasoning && options?.thinkingEnabled) {
		if (supportsAdaptiveThinking(model)) {
			(params as any).thinking = {
				type: "adaptive",
				...(options.thinkingDisplay ? { display: options.thinkingDisplay } : {}),
			};
			if (options.effort) (params as any).output_config = { effort: options.effort };
		} else {
			(params as any).thinking = { type: "enabled", budget_tokens: options.thinkingBudgetTokens || 1024 };
		}
	}

	if (options?.metadata) {
		const userId = options.metadata.user_id;
		if (typeof userId === "string") {
			params.metadata = { user_id: userId };
		}
	}

	if (options?.toolChoice) {
		if (typeof options.toolChoice === "string") {
			params.tool_choice = { type: options.toolChoice };
		} else {
			params.tool_choice = options.toolChoice;
		}
	}

	return params;
}

type ManagedMessageIdentity = { provider: string; api: string };

function isAnthropicEffort(value: unknown): value is AnthropicEffort {
	return (
		value === "low" ||
		value === "medium" ||
		value === "high" ||
		value === "xhigh" ||
		value === "max"
	);
}

// Normalize tool call IDs to match Anthropic's required pattern and length
function normalizeToolCallId(id: string): string {
	return id.replace(/[^a-zA-Z0-9_-]/g, "_").slice(0, 64);
}

// Block types that may carry the single conversation-history cache breakpoint (Pi 1.1.0 parity).
const CONVERSATION_BREAKPOINT_BLOCK_TYPES = new Set(["text", "image", "tool_result", "tool_addition", "tool_removal"]);
export function convertMessages(
	messages: Message[],
	model: Model<"anthropic-messages">,
	isOAuthToken: boolean,
	cacheControl?: { type: "ephemeral"; ttl?: "1h" },
	managedIdentity?: ManagedMessageIdentity,
	convertToolDefinitions?: (tools: Tool[]) => Anthropic.Messages.Tool[],
): MessageParam[] {
	const params: MessageParam[] = [];
	const pendingSystemMessages: MessageParam[] = [];
	const flushPendingSystemMessages = () => {
		params.push(...pendingSystemMessages);
		pendingSystemMessages.length = 0;
	};

	// Transform messages for cross-provider compatibility
	const transformedMessages = transformMessages(messages, model, normalizeToolCallId);

	for (let i = 0; i < transformedMessages.length; i++) {
		const msg = transformedMessages[i];

		if (msg.role === "system") {
			const text = renderSystemMessageUpdate(msg);
			const blocks: ContentBlockParam[] = [];
			if (text.length > 0) {
				blocks.push({ type: "text", text: sanitizeSurrogates(text) });
			}
			if (convertToolDefinitions) {
				const added = msg.toolsAdded ?? [];
				// A new definition under the same name replaces the old one, so no removal is needed.
				const redefined = new Set(added.map((tool) => tool.name));
				for (const tool of msg.toolsRemoved ?? []) {
					if (redefined.has(tool.name)) continue;
