import { afterEach, describe, expect, it, mock } from "bun:test";
import { transcript } from "./helpers/transcript";

const originalFetch = globalThis.fetch;
const originalAnthropicCcApiKey = process.env.ANTHROPIC_CC_API_KEY;
const originalAnthropicApiKey = process.env.ANTHROPIC_API_KEY;

function buildModel() {
	return {
		id: "claude-opus-4-6",
		name: "Claude Opus 4.6 (anthropic-cc)",
		api: "anthropic-cc-api",
		provider: "anthropic-cc",
		baseUrl: "https://api.anthropic.com",
		reasoning: true,
		input: ["text"],
		cost: { input: 0, output: 0, cacheRead: 0, cacheWrite: 0 },
		contextWindow: 1000000,
		maxTokens: 128000,
	} as any;
}

function buildMessageStartEvent(usage: Record<string, number>) {
	return {
		type: "message_start",
		message: {
			id: "msg_123",
			type: "message",
			role: "assistant",
			content: [],
			model: "claude-opus-4-6",
			stop_reason: null,
			stop_sequence: null,
			usage,
		},
	};
}

function buildSsePayload(events: Array<Record<string, any>>) {
	return events.map((event) => `event: ${event.type}\ndata: ${JSON.stringify(event)}`).join("\n\n") + "\n\n";
}

function mockStreamFetch(payload: string) {
	globalThis.fetch = mock(async (_url: string, _init?: RequestInit) =>
		new Response(
			new ReadableStream({
				start(controller) {
					controller.enqueue(new TextEncoder().encode(payload));
					controller.close();
				},
			}),
			{
				status: 200,
				headers: { "content-type": "text/event-stream" },
			},
		) as any,
	) as any;
}

function toHeaderMap(headers: HeadersInit | undefined): Record<string, string> {
	if (!headers) return {};
	if (headers instanceof Headers) return Object.fromEntries(headers.entries());
	if (Array.isArray(headers)) return Object.fromEntries(headers);
	return headers as Record<string, string>;
}

afterEach(() => {
	globalThis.fetch = originalFetch;
	if (originalAnthropicCcApiKey === undefined) delete process.env.ANTHROPIC_CC_API_KEY;
	else process.env.ANTHROPIC_CC_API_KEY = originalAnthropicCcApiKey;
	if (originalAnthropicApiKey === undefined) delete process.env.ANTHROPIC_API_KEY;
	else process.env.ANTHROPIC_API_KEY = originalAnthropicApiKey;
});

